1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return an empty grid for an empty grid", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	
9	  it("should let a single live cell die from underpopulation", () => {
10	    expect(nextGeneration([[0, 0]])).toEqual([]);
11	  });
12	
13	  it("should let two adjacent live cells die from underpopulation", () => {
14	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
15	  });
16	
17	  it("should let a live cell with two live neighbors survive", () => {
18	    expect(nextGeneration([[1, 0], [1, 1], [1, 2]])).toContainEqual([1, 1]);
19	  });
20	
21	  it("should let a live cell with three live neighbors survive", () => {
22	    expect(
23	      nextGeneration([
24	        [0, 0],
25	        [1, 0],
26	        [2, 0],
27	        [1, 1],
28	      ]),
29	    ).toContainEqual([1, 0]);
30	  });
31	
32	  it("should let a live cell with more than three live neighbors die from overpopulation", () => {
33	    expect(
34	      nextGeneration([
35	        [1, 1],
36	        [0, 0],
37	        [0, 1],
38	        [1, 0],
39	        [2, 2],
40	      ]),
41	    ).not.toContainEqual([1, 1]);
42	  });
43	
44	  it("should bring a dead cell with exactly three live neighbors to life", () => {
45	    expect(
46	      nextGeneration([
47	        [0, 0],
48	        [1, 0],
49	        [0, 1],
50	      ]),
51	    ).toContainEqual([1, 1]);
52	  });
53	  it("should keep a block unchanged as a still life", () => {
54	    const block: Cell[] = [
55	      [0, 0],
56	      [1, 0],
57	      [0, 1],
58	      [1, 1],
59	    ];
60	    const result = nextGeneration(block);
61	    expect(result).toHaveLength(4);
62	    expect(result).toEqual(expect.arrayContaining(block));
63	  });
64	  it.todo("should oscillate a vertical blinker into a horizontal blinker");
65	  it.todo("should oscillate a horizontal blinker back into a vertical blinker");
66	  it.todo("should handle cells at negative coordinates");
67	});
